const _qbc={};
function _loadQB(name){const v={science:'_qbSci',olympiad:'_qbOly',words:'_qbWords'}[name];if(window[v]||document.querySelector('script[data-qb="'+name+'"]'))return;const sc=document.createElement('script');sc.src='/shared/qbank-'+name+'.js';sc.async=true;sc.dataset.qb=name;document.head.appendChild(sc);}
function _qbPool(subj,lvl,old){const w=subj==='sci'?window._qbSci:window._qbOly;if(!w||!w[lvl])return old;const k=subj+lvl;if(!_qbc[k])_qbc[k]=w[lvl].map(a=>({q:a[0],answer:a[1],options:a.slice(1)}));return _qbc[k].concat(old);}
const _wqc={};
function _wordPool(lvl){const w=window._qbWords;if(!w||!w[lvl])return[];if(!_wqc[lvl]){const cats=window._qbWordCats||[];_wqc[lvl]=w[lvl].map(it=>{const word=it[0],h=it[1],n=word.length;const first=word[0];let hint;if(typeof h==='string')hint=h+' · '+n+' letters';else if(h>=0){const c=cats[h]||'a word';hint=c.charAt(0).toUpperCase()+c.slice(1)+' · '+n+' letters · starts with '+first;}else hint='A word with '+n+' letters · starts with '+first;return{word,hint};});}return _wqc[lvl];}
